const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextInt() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        let res = 0;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            res = res * 10 + (input.charCodeAt(pos) - 48);
            pos++;
        }
        return res;
    }

    const n = nextInt();
    if (n === null) return;

    const stack = [];
    for (let i = 0; i < n; i++) {
        const val = nextInt();
        if (val === 0) {
            stack.pop();
        } else {
            stack.push(val);
        }
    }

    let sum = 0;
    for (let i = 0; i < stack.length; i++) {
        sum += stack[i];
    }

    console.log(sum);
}

main();
